export function findingObjectionDraft(task,id){
 const view=openTaskView(task);if(task.display_revision&&task.display_revision!==task.identity.revision)throw Error('当前为历史成果，请切回最新版本后提出异议。');
 const finding=view.findings.find(f=>f.id===id);if(!finding)throw Error('发现版本已变化，请查看当前成果。');
 return '针对版本 '+finding.evidence.revision+' 的发现「'+finding.claim+'」（'+finding.value+' '+finding.unit+'），我的异议是：';
}

