// Application-owned report editing tail remains in durable evidence, not user conversation.
function visibleAnalysisMessages(task){
 const messages=task.checkpoint?.messages??[],visible=[];
 const ownedExecutionAction='当前实际动作：用户已经采纳方案并要求执行计算与独立核验。下列文字是准备阶段原始需求，用于确定分析意图；其中先准备、暂不计算及采纳后再算等阶段文字不覆盖已经发生的采纳动作。实际执行仍受当前获准资料、绑定范围及停止检查约束。\n采纳的原始分析要求：'+task.question;
 for(let i=0;i<messages.length;i++){const m=messages[i];if(i>0&&m.speaker==='user'&&task.confirmed_plan?.revision===task.identity.revision&&m.text===ownedExecutionAction)continue;if(i>0&&m.speaker==='user'&&m.text.startsWith('JuanerAI.report-edit.v1\n')){try{const x=JSON.parse(m.text.slice('JuanerAI.report-edit.v1\n'.length));if(x.version==='1.0'&&x.identity?.task_id===task.identity.task_id){if(messages[i+1]?.speaker==='assistant')i++;continue;}}catch{}}visible.push(m);}
 return visible;
}
